// Extract the generated image from Gemini HTTP response
// Response shape: { candidates: [{ content: { parts: [{ inlineData: { mimeType, data } }] } }] }
const results = [];

for (const item of items) {
  const candidates = item.json.candidates;
  if (!candidates || candidates.length === 0) {
    throw new Error('Gemini returned no candidates. Full response: ' + JSON.stringify(item.json));
  }

  const parts = candidates[0].content.parts;
  const imagePart = parts.find(p => p.inlineData && p.inlineData.data);

  if (!imagePart) {
    throw new Error('No image part found in Gemini response. Parts: ' + JSON.stringify(parts.map(p => Object.keys(p))));
  }

  const base64Image = imagePart.inlineData.data;
  const mimeType = imagePart.inlineData.mimeType || 'image/png';

  // Convert base64 to binary buffer for downstream nodes
  const binaryData = Buffer.from(base64Image, 'base64');

  results.push({
    json: {
      generatedImageBase64: base64Image,
      generatedImageMimeType: mimeType,
    },
    binary: {
      data: await this.helpers.prepareBinaryData(binaryData, 'generated_model_image.png', mimeType)
    }
  });
}

return results;

// Set Metadata — builds formatted fields per item and preserves binary image.
const results = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const source = $('Get Product Image Urls').all()[index].json;

  const productName  = source.productName  || '';
  const productPrice = source.productPrice;
  const currency     = source.currency     || 'USD';
  const platform     = source.platform     || 'TikTok';

  const symbols = {
    USD: '$', EUR: '€', GBP: '£', AUD: 'A$', CAD: 'C$',
    NGN: '₦', ZAR: 'R', JPY: '¥', INR: '₹', BRL: 'R$', MXN: 'MX$'
  };
  const symbol = symbols[currency] || (currency + ' ');
  const formattedPrice = (!productPrice || productPrice === 0)
    ? ''
    : symbol + Number(productPrice).toFixed(2) + ' ' + currency;

  results.push({
    json: {
      productName,
      productPrice,
      currency,
      platform,
      formattedPrice,
      editedimage: item.json.editedimage,
    },
    binary: item.binary,
  });
}

return results;

// Restore Set Metadata fields after Update row(s) wiped them.
// Uses index-aware lookup so each item in the batch gets its own metadata.
const results = [];

for (let index = 0; index < items.length; index++) {
  const meta = $('Set Metadata').all()[index].json;

  results.push({
    json: {
      productName:    meta.productName,
      productPrice:   meta.productPrice,
      currency:       meta.currency,
      platform:       meta.platform,
      formattedPrice: meta.formattedPrice,
    }
  });
}

return results;
